static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<0x80)continue;unsigned n;uint32_t v;if(c>=0xc2&&c<=0xdf){n=1;v=c&31;}else if(c>=0xe0&&c<=0xef){n=2;v=c&15;}else if(c>=0xf0&&c<=0xf4){n=3;v=c&7;}else return false;if(i+n>s.size())return false;for(unsigned j=0;j<n;j++){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;v=(v<<6)|(d&63);}if((n==2&&v<0x800)||(n==3&&v<0x10000)||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int decodepath(const string&target,string&path){if(target.empty()||target[0]!='/'||target.find('#')!=string::npos)return 400;size_t q=target.find('?');string p=target.substr(0,q);path.clear();for(size_t i=0;i<p.size();i++){unsigned char c=p[i];if(c=='%'){if(i+2>=p.size()||hex(p[i+1])<0||hex(p[i+2])<0)return 400;c=(hex(p[i+1])<<4)|hex(p[i+2]);i+=2;}if(c==0||c=='\\'||c<32||c==127)return 400;path.push_back(c);}if(!utf8(path))return 400;size_t a=0;while(a<=path.size()){size_t b=path.find('/',a);if(b==string::npos)b=path.size();if(path.substr(a,b-a)=="..")return 403;if(b==path.size())break;a=b+1;}return 0;}
struct Header{string name,value;};
struct Req{string method,target,path,version;vector<Header> headers;bool close=false,head=false,gateway=false;};
static bool has_token(const string&s,const string&needle){size_t a=0;while(a<=s.size()){size_t b=s.find(',',a);if(b==string::npos)b=s.size();if(lower(trim(s.substr(a,b-a)))==needle)return true;if(b==s.size())break;a=b+1;}return false;}
static int parse_req(const string&s,Req&r){size_t e=s.find("\r\n");if(e==string::npos)return 400;string line=s.substr(0,e);size_t a=line.find(' '),b=a==string::npos?string::npos:line.find(' ',a+1);if(a==string::npos||b==string::npos||line.find(' ',b+1)!=string::npos)return 400;r.method=line.substr(0,a);r.target=line.substr(a+1,b-a-1);r.version=line.substr(b+1);if(!token(r.method)||r.target.empty()||(r.version!="HTTP/1.0"&&r.version!="HTTP/1.1"))return 400;for(unsigned char c:r.target)if(c<=32||c==127)return 400;int p=decodepath(r.target,r.path);if(p)return p;r.gateway=r.path.size()>=9&&r.path.compare(0,9,"/gateway/")==0;r.head=r.method=="HEAD";r.close=r.version=="HTTP/1.0";int hosts=0,cls=0;bool te=false;size_t pos=e+2;while(pos<s.size()){e=s.find("\r\n",pos);if(e==string::npos)return 400;if(e==pos){pos=e+2;break;}string x=s.substr(pos,e-pos);if(x.empty()||x[0]==' '||x[0]=='\t')return 400;size_t col=x.find(':');if(col==string::npos)return 400;string n=x.substr(0,col),v=trim(x.substr(col+1));if(!token(n))return 400;for(unsigned char c:v)if(c==0||c=='\r'||c=='\n'||(c<32&&c!='\t')||c==127)return 400;n=lower(n);if(n=="host"){hosts++;if(v.empty())return 400;}if(n=="content-length"){cls++;unsigned long long z;if(!dec(v,z)||z!=0)return 400;}if(n=="transfer-encoding")te=true;if(n=="connection"&&has_token(v,"close"))r.close=true;r.headers.push_back({n,v});pos=e+2;}if(pos!=s.size()||cls>1||te)return 400;if(r.gateway&&hosts!=1)return 400;if(r.method!="GET"&&r.method!="HEAD")return 405;return 0;}
static int localfile(shared_ptr<Config> c,const string&path,string&body){if(path.empty()||path.back()=='/')return 403;int dir=dup(c->rootfd);if(dir<0)return 500;size_t a=1;int result=404;while(a<=path.size()){size_t b=path.find('/',a);if(b==string::npos)b=path.size();string part=path.substr(a,b-a);a=b+1;if(part.empty()||part=="."){if(b==path.size()){result=403;break;}continue;}struct stat st;if(fstatat(dir,part.c_str(),&st,AT_SYMLINK_NOFOLLOW)<0){result=(errno==EACCES?403:404);break;}if(S_ISLNK(st.st_mode)){result=403;break;}bool last=b==path.size();if(!last){if(!S_ISDIR(st.st_mode)){result=403;break;}int nd=openat(dir,part.c_str(),O_RDONLY|O_DIRECTORY|O_NOFOLLOW|O_CLOEXEC);if(nd<0){result=(errno==ELOOP||errno==EACCES)?403:404;break;}close(dir);dir=nd;continue;}if(!S_ISREG(st.st_mode)){result=403;break;}int fd=openat(dir,part.c_str(),O_RDONLY|O_NOFOLLOW|O_NONBLOCK|O_CLOEXEC);if(fd<0){result=(errno==ELOOP||errno==EACCES)?403:404;break;}if(fstat(fd,&st)<0||!S_ISREG(st.st_mode)){close(fd);result=403;break;}if(st.st_size<0||st.st_size>128*1024*1024){close(fd);result=500;break;}body.resize((size_t)st.st_size);size_t off=0;while(off<body.size()){ssize_t n=read(fd,&body[off],body.size()-off);if(n>0)off+=n;else if(n<0&&errno==EINTR)continue;else break;}close(fd);if(off!=body.size()){body.clear();result=500;}else result=200;break;}close(dir);return result;}
static const char*reason(int code){switch(code){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";case 500:return "Internal Server Error";case 502:return "Bad Gateway";default:return "Origin Response";}}
struct Conn{int fd=-1,up=-1;SSL*ssl=nullptr;shared_ptr<Config> cfg;string in,out,ureq,uin;size_t outpos=0,upos=0;ll idle=0,first=0,deadline=0;unsigned long long count=0;bool closeafter=false,head=false,upclose=false,reused=false;int phase=0;uint32_t want=0;size_t ubody=0;unsigned long long ulen=0;int ustatus=0;string uextra;~Conn(){if(ssl)SSL_free(ssl);if(up>=0)close(up);if(fd>=0)close(fd);}};
static int ep=-1;static unordered_map<int,Conn*> clients,ups;static shared_ptr<Config> current_config;
static void mod(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}
static void add(int fd,uint32_t ev){epoll_event e{};e.events=ev;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}
static void dropup(Conn*c){if(c->up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c->up,nullptr);ups.erase(c->up);if(c->ssl){SSL_free(c->ssl);c->ssl=nullptr;}close(c->up);c->up=-1;}c->phase=0;}
static void killconn(Conn*c){dropup(c);epoll_ctl(ep,EPOLL_CTL_DEL,c->fd,nullptr);clients.erase(c->fd);delete c;}
static void response(Conn*c,int status,string body,unsigned long long length,const string&extra=""){c->count++;if(c->count>=c->cfg->maxreq)c->closeafter=true;string h="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(length)+"\r\nConnection: "+(c->closeafter?"close":"keep-alive")+"\r\n"+extra+"\r\n";if(!c->head)h+=body;c->out.swap(h);c->outpos=0;c->deadline=nowms()+c->cfg->wtime;mod(c->fd,EPOLLOUT);}
static void failure(Conn*c,int status,bool closeit){dropup(c);c->closeafter|=closeit;response(c,status,"",0);}
static bool skiphop(const string&n,const unordered_set<string>&named){return n=="connection"||n=="proxy-connection"||n=="keep-alive"||n=="transfer-encoding"||n=="te"||n=="trailer"||n=="upgrade"||n=="content-length"||n=="proxy-authorization"||n=="proxy-authenticate"||named.count(n);}
static void splitnames(const string&s,unordered_set<string>&names){size_t a=0;while(a<=s.size()){size_t b=s.find(',',a);if(b==string::npos)b=s.size();names.insert(lower(trim(s.substr(a,b-a))));if(b==s.size())break;a=b+1;}}
static void startup(Conn*c,const Req&r){unordered_set<string> named;for(auto&h:r.headers)if(h.name=="connection")splitnames(h.value,named);string target=r.target.substr(8);if(target.empty()||target[0]!='/'){failure(c,400,true);return;}c->ureq=r.method+" "+target+" HTTP/1.1\r\n";for(auto&h:r.headers){if(skiphop(h.name,named))continue;c->ureq+=h.name+": "+h.value+"\r\n";}c->ureq+="Content-Length: 0\r\nConnection: keep-alive\r\n\r\n";c->upos=0;c->uin.clear();c->ubody=0;c->uextra.clear();c->upclose=false;c->deadline=nowms()+c->cfg->wtime;mod(c->fd,0);if(c->up>=0&&c->phase==5){c->phase=3;c->reused=true;mod(c->up,EPOLLOUT);return;}c->reused=false;int fd=socket(c->cfg->oa.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){failure(c,502,false);return;}c->up=fd;c->ssl=SSL_new(c->cfg->ctx);if(!c->ssl||SSL_set_fd(c->ssl,fd)!=1||SSL_set_tlsext_host_name(c->ssl,c->cfg->name.c_str())!=1||SSL_set1_host(c->ssl,c->cfg->name.c_str())!=1){failure(c,502,false);return;}SSL_set_connect_state(c->ssl);int res=connect(fd,(sockaddr*)&c->cfg->oa,c->cfg->olen);if(res<0&&errno!=EINPROGRESS){failure(c,502,false);return;}c->phase=1;c->deadline=nowms()+c->cfg->wtime;ups[fd]=c;add(fd,EPOLLOUT);mod(c->fd,0);}
static void process(Conn*c){if(c->cfg!=current_config){dropup(c);c->cfg=current_config;}if(c->in.empty()){c->first=0;c->idle=nowms()+c->cfg->idle;mod(c->fd,EPOLLIN);return;}size_t end=c->in.find("\r\n\r\n");if(end==string::npos){for(size_t i=0;i<c->in.size();i++){unsigned char ch=c->in[i];if(ch==0||(ch=='\n'&&(i==0||c->in[i-1]!='\r'))||(ch=='\r'&&i+1<c->in.size()&&c->in[i+1]!='\n')){c->head=false;failure(c,400,true);return;}}if(c->in.size()>c->cfg->header){c->head=false;failure(c,431,true);return;}mod(c->fd,EPOLLIN);return;}end+=4;if(end>c->cfg->header){c->head=false;failure(c,431,true);return;}string raw=c->in.substr(0,end);c->in.erase(0,end);Req r;int status=parse_req(raw,r);c->head=r.head;c->closeafter=r.close;c->first=c->in.empty()?0:nowms();if(status){failure(c,status,status==400||status==431);return;}if(r.gateway){startup(c,r);return;}string body;int st=localfile(c->cfg,r.path,body);unsigned long long sz=body.size();response(c,st,move(body),sz,st==200?"Content-Type: application/octet-stream\r\n":"");}
static bool parse_up(Conn*c){size_t end=c->uin.find("\r\n\r\n");if(end==string::npos)return false;if(end>65536){c->ustatus=-1;return true;}string h=c->uin.substr(0,end+2);size_t p=h.find("\r\n");if(p==string::npos){c->ustatus=-1;return true;}string line=h.substr(0,p);if(line.size()<12||(line.compare(0,9,"HTTP/1.1 ")&&line.compare(0,9,"HTTP/1.0 "))||line[9]<'1'||line[9]>'5'||line[10]<'0'||line[10]>'9'||line[11]<'0'||line[11]>'9'||(line.size()>12&&line[12]!=' ')){c->ustatus=-1;return true;}c->ustatus=(line[9]-'0')*100+(line[10]-'0')*10+line[11]-'0';c->upclose=line.compare(0,8,"HTTP/1.0")==0;if(c->ustatus<200){c->ustatus=-1;return true;}vector<Header> hs;int lens=0;bool te=false;unordered_set<string> named;size_t at=p+2;while(at<h.size()){size_t q=h.find("\r\n",at);if(q==string::npos){c->ustatus=-1;return true;}string x=h.substr(at,q-at);if(x.empty()){at=q+2;break;}size_t colon=x.find(':');if(colon==string::npos||!token(x.substr(0,colon))){c->ustatus=-1;return true;}string n=lower(x.substr(0,colon)),v=trim(x.substr(colon+1));for(unsigned char ch:v)if(ch==0||ch=='\r'||ch=='\n'||(ch<32&&ch!='\t')||ch==127){c->ustatus=-1;return true;}if(n=="content-length"){lens++;if(!dec(v,c->ulen)||c->ulen>128*1024*1024){c->ustatus=-1;return true;}}if(n=="transfer-encoding")te=true;if(n=="connection"){splitnames(v,named);if(has_token(v,"close"))c->upclose=true;}hs.push_back({n,v});at=q+2;}if(lens!=1||te){c->ustatus=-1;return true;}for(auto&x:hs)if(!skiphop(x.name,named))c->uextra+=x.name+": "+x.value+"\r\n";c->ubody=end+4;return true;}
static void up_event(Conn*c,uint32_t events){if(c->phase==5){char b;int ret=SSL_peek(c->ssl,&b,1);if(ret>0){dropup(c);return;}int e=SSL_get_error(c->ssl,ret);if(e==SSL_ERROR_WANT_READ){mod(c->up,EPOLLIN);return;}if(e==SSL_ERROR_WANT_WRITE){mod(c->up,EPOLLOUT);return;}dropup(c);return;}if(c->phase==1){int err=0;socklen_t l=sizeof(err);if(getsockopt(c->up,SOL_SOCKET,SO_ERROR,&err,&l)<0||err){failure(c,502,false);return;}c->phase=2;}for(int loops=0;loops<16;loops++){int ret=0;if(c->phase==2){ret=SSL_connect(c->ssl);if(ret==1){if(SSL_get_verify_result(c->ssl)!=X509_V_OK){failure(c,502,false);return;}c->phase=3;c->deadline=nowms()+c->cfg->wtime;continue;}}else if(c->phase==3){ret=SSL_write(c->ssl,c->ureq.data()+c->upos,(int)(c->ureq.size()-c->upos));if(ret>0){c->upos+=ret;c->deadline=nowms()+c->cfg->wtime;if(c->upos==c->ureq.size())c->phase=4;continue;}}else if(c->phase==4){char buf[16384];ret=SSL_read(c->ssl,buf,sizeof(buf));if(ret>0){c->uin.append(buf,ret);c->deadline=nowms()+c->cfg->wtime;if(!c->ubody){if(!parse_up(c)){if(c->uin.size()>65536){failure(c,502,false);return;}continue;}if(c->ustatus<0){failure(c,502,false);return;}}unsigned long long need=(c->head||c->ustatus==204||c->ustatus==304)?0:c->ulen;if(c->uin.size()-c->ubody>=need){string body;if(need)body=c->uin.substr(c->ubody,(size_t)need);int st=c->ustatus;auto len=c->ulen;string extra=move(c->uextra);if(c->upclose||c->uin.size()-c->ubody!=need)dropup(c);else {c->phase=5;mod(c->up,EPOLLIN);}c->uin.clear();response(c,st,move(body),len,extra);return;}continue;}}else return;int err=SSL_get_error(c->ssl,ret);if(err==SSL_ERROR_WANT_READ){mod(c->up,EPOLLIN);return;}if(err==SSL_ERROR_WANT_WRITE){mod(c->up,EPOLLOUT);return;}failure(c,502,false);return;}mod(c->up,c->phase==3?EPOLLOUT:EPOLLIN);}
static void client_event(Conn*c,uint32_t ev){if(!c->out.empty()){if(ev&EPOLLOUT){while(c->outpos<c->out.size()){ssize_t n=send(c->fd,c->out.data()+c->outpos,c->out.size()-c->outpos,MSG_NOSIGNAL);if(n>0){c->outpos+=n;c->deadline=nowms()+c->cfg->wtime;}else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;else{killconn(c);return;}}c->out.clear();if(c->closeafter){killconn(c);return;}process(c);return;}if(ev&(EPOLLERR|EPOLLHUP)){killconn(c);return;}return;}if(c->up>=0&&c->phase!=5){if(ev&(EPOLLERR|EPOLLHUP)){killconn(c);return;}return;}if(ev&EPOLLIN){char b[16384];for(;;){size_t cap=(size_t)min<unsigned long long>(c->cfg->header*min<unsigned long long>(c->cfg->depth,1024),4*1024*1024);cap=max<size_t>(cap,c->cfg->header+1);if(c->in.size()>=cap)break;size_t ask=min(sizeof(b),cap-c->in.size());ssize_t n=recv(c->fd,b,ask,0);if(n>0){if(c->in.empty())c->first=nowms();c->in.append(b,n);if(c->in.find("\r\n\r\n")!=string::npos||c->in.size()>c->cfg->header)break;}else if(n==0){if(c->in.empty()){killconn(c);return;}break;}else if(errno==EINTR)continue;else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{killconn(c);return;}}process(c);return;}if(ev&(EPOLLERR|EPOLLHUP|EPOLLRDHUP)){killconn(c);return;}}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;signal(SIGPIPE,SIG_IGN);struct sigaction sa{};sa.sa_handler=hup;sigemptyset(&sa.sa_mask);sigaction(SIGHUP,&sa,nullptr);OPENSSL_init_ssl(0,nullptr);string path=argv[2];auto cfg=loadconfig(path);if(!cfg)return 1;current_config=cfg;int listener=socket(cfg->la.ss_family,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int yes=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&yes,sizeof(yes));if(bind(listener,(sockaddr*)&cfg->la,cfg->llen)<0||listen(listener,1024)<0)return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;add(listener,EPOLLIN);epoll_event events[512];for(;;){if(reload_flag){reload_flag=0;auto n=loadconfig(path);if(n&&n->listen==cfg->listen){cfg=n;current_config=n;}}int n=epoll_wait(ep,events,512,100);if(n<0&&errno!=EINTR)break;for(int i=0;i<n;i++){int fd=events[i].data.fd;if(fd==listener){for(;;){int d=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(d<0){if(errno==EINTR)continue;break;}if(clients.size()>=cfg->maxconn){close(d);continue;}Conn*c=new Conn;c->fd=d;c->cfg=cfg;c->idle=nowms()+cfg->idle;clients[d]=c;add(d,EPOLLIN);}continue;}auto it=clients.find(fd);if(it!=clients.end()){client_event(it->second,events[i].events);continue;}auto iu=ups.find(fd);if(iu!=ups.end())up_event(iu->second,events[i].events);}ll t=nowms();vector<Conn*> expired;for(auto&kv:clients){Conn*c=kv.second;if((c->up>=0&&c->phase!=5)||!c->out.empty()){if(t>=c->deadline)expired.push_back(c);}else if(c->first){if(t-c->first>=(ll)c->cfg->htime)expired.push_back(c);}else if(t>=c->idle)expired.push_back(c);}for(Conn*c:expired){if(c->up>=0&&c->phase!=5)failure(c,502,false);else killconn(c);}}return 0;}
